import assert from 'node:assert/strict';
import {randomBytes,randomUUID} from 'node:crypto';
import {readFileSync} from 'node:fs';
import {generationFamilyModule} from '../scoped-shared-consent-module.mjs';
import {createOuchiFamilyNativePreparation} from '../../../lib/ouchi-family-native-preparation.mjs';
import {createDeletionJournal} from '../kakei-completion/lib/shared-deletion-journal.mjs';
import {fixtureTOTP} from '../scoped-native-gotrue.mjs';
export async function verifyGenerationFamilyOriginals({admin,coordinator,issuer,auth,transaction,projectID,afterSchema,afterActorSetup}){
 await admin.query(readFileSync('tests/fixtures/generation-family-originals-20261021/protocol.sql','utf8'));
 if(afterSchema)await afterSchema();
 async function actor(){const user=randomUUID(),epoch=randomUUID(),email=user+'@fixture.invalid',password=randomBytes(30).toString('base64url');await auth.createFixtureUser(user,email,password);const login=await auth.request('/token?grant_type=password',{email,password});const f=await auth.request('/factors',{factor_type:'totp',friendly_name:'Generation family original'},login.access_token);const c=await auth.request('/factors/'+f.id+'/challenge',{},login.access_token);const promoted=await auth.request('/factors/'+f.id+'/verify',{challenge_id:c.id,code:fixtureTOTP(f.totp.secret)},login.access_token);const sid=JSON.parse(Buffer.from(promoted.access_token.split('.')[1],'base64url')).session_id;await admin.query('insert into maintenance_private.account_access values($1,true)',[user]);await admin.query('insert into maintenance_private.app_epochs values($1,$2,true)',[user,epoch]);await admin.query('insert into maintenance_private.app_session_epochs values($1,$2,$3)',[sid,user,epoch]);return {user,epoch,token:promoted.access_token,aal1:login.access_token};}
 const owner=await actor(),receiver=await actor(),receiver2=await actor(),home=randomUUID(),home2=randomUUID(),product=randomUUID();await admin.query('insert into public.homes(id,owner_id) values($1,$2)',[home,owner.user]);await admin.query('insert into public.home_members("homeId",user_id,nickname) values($1,$2,$3)',[home,receiver.user,'Original receiver']);await admin.query('insert into public.products(id,"homeId","categoryId",name) values($1,$2,$3,$4)',[product,home,'air','Generation original retained']);
 await admin.query('insert into public.homes(id,owner_id) values($1,$2)',[home2,owner.user]);await admin.query('insert into public.home_members("homeId",user_id,nickname) values($1,$2,$3)',[home2,receiver2.user,'Second original receiver']);
 await admin.query((await admin.query("select format('create policy generation_original_%s on private.kb_shared_deletion_journal for all to shared_retirement_backend using(user_id=%L::uuid) with check(user_id=%L::uuid)',replace($1::text,'-',''),$1::text,$1::text) sql",[owner.user])).rows[0].sql);
 const extraCase=afterActorSetup?await afterActorSetup({owner,receiver,receiver2,home,home2,product}):{};
 let policyLive=true,covered=true;const key=randomBytes(32);
 const policyReader=Object.assign(async()=>Object.freeze({projectID,authVersion:'v2.197.0',assuranceMode:'highest-current-aal/v1',singleSession:false,totpVerify:true,timeboxSeconds:null,inactivitySeconds:null}),{isCurrent:()=>policyLive});
 const getUser=async(token,signal)=>{signal.throwIfAborted();return {data:{user:await auth.request('/user',undefined,token)},error:null};};
 const make=async()=>{const scope={protocolVersion:2,kind:'shared-account',requestID:randomUUID(),userID:owner.user,leaseToken:randomUUID(),inventoryDigest:'4'.repeat(64),apps:[{app:'ouchi-maintenance',requestID:randomUUID(),scopeID:owner.epoch}]};const fixed={...scope};delete fixed.leaseToken;await admin.query("insert into private.kb_shared_deletion_journal values($1,$2,$3,'requested',null,null,'{}')",[scope.requestID,owner.user,fixed]);return {scope,generationID:randomUUID(),nativeLease:randomUUID(),homes:[{homeID:home,successorID:receiver.user},{homeID:home2,successorID:receiver2.user}]};};
 const options=x=>({...x,key,projectID,policyReader,getUser,verifyNoDispatch:async(s,tx,signal)=>{signal.throwIfAborted();return covered&&JSON.stringify(s)===JSON.stringify(x.scope);}});
 const first=await make(),prep1=createOuchiFamilyNativePreparation(options(first)),original1=generationFamilyModule.createGenerationFamilyOriginals(options(first));
 await transaction(coordinator,tx=>prep1.prepare(first.scope,tx));
 await assert.rejects(transaction(issuer,tx=>original1.issue(owner.aal1,home,tx)),/Real current generation AAL2/);
 assert.equal(await transaction(coordinator,tx=>original1.requested(first.scope,tx)),null,'No original set is never consent');
 await assert.rejects(transaction(coordinator,tx=>tx.query("update private.kb_shared_deletion_journal set status='processing',lease_token=$2,lease_until=clock_timestamp()+interval '1 minute' where request_id=$1",[first.scope.requestID,first.scope.leaseToken])),/Current family original set|Exact generation originals/,'Raw root transition without complete originals cannot COMMIT');
 const decoded=JSON.parse(Buffer.from(owner.token.split('.')[1],'base64url'));
 await transaction(issuer,async tx=>{try{const check=await tx.query(generationFamilyModule.GENERATION_FAMILY_AUTH_SQL,[first.scope.requestID,home,owner.user,decoded.session_id,first.nativeLease,'aal2',decoded.amr.find(x=>x.method==='totp').timestamp*1000,null,null,first.generationID]);assert.equal(check.rows.length,1,'Actual fixed generation Auth RPC must confirm real TOTP');}catch(e){console.error('Fixed generation Auth diagnostic',JSON.stringify({code:e.code,where:e.where}));throw e;}});
 const a=await transaction(issuer,tx=>original1.issue(owner.token,home,tx));assert.equal(a.payload.generationID,first.generationID);assert.equal(a.payload.epochID,owner.epoch);
 assert.equal(await transaction(coordinator,tx=>original1.requested(first.scope,tx)),null,'Owner original alone does not approve successor');
 const b=await transaction(issuer,tx=>original1.issue(receiver.token,home,tx));assert.equal(b.payload.epochID,receiver.epoch);assert.equal(b.payload.homeID,home);
 assert.equal(await transaction(coordinator,tx=>original1.requested(first.scope,tx)),null,'One home approved does not cover the second home/successor');
 await transaction(issuer,tx=>original1.issue(owner.token,home2,tx));await transaction(issuer,tx=>original1.issue(receiver2.token,home2,tx));
 assert.deepEqual(await transaction(issuer,tx=>original1.issue(owner.token,home,tx)),a,'Replay keeps original payload/signature/expiry');
 const saved=(await admin.query('select * from maintenance_private.generation_family_originals where generation_id=$1 order by home_id,actor_id',[first.generationID])).rows;assert.equal(saved.length,4);
 const cancel1=createDeletionJournal({transaction:work=>transaction(coordinator,work)},{'after-cancel':(s,tx)=>prep1.cancelRequested(s,tx)});assert.equal(await cancel1.cancel(first.scope),true);
 assert.deepEqual((await admin.query('select * from maintenance_private.generation_family_originals where generation_id=$1 order by home_id,actor_id',[first.generationID])).rows,saved,'Cancelled generation real AAL2 originals remain immutable');
 const next=await make(),prep=createOuchiFamilyNativePreparation(options(next)),original=generationFamilyModule.createGenerationFamilyOriginals(options(next));await transaction(coordinator,tx=>prep.prepare(next.scope,tx));
 assert.equal(await transaction(coordinator,tx=>original.requested(next.scope,tx)),null,'Old home/generation originals cannot approve new root');
 const nextA=await transaction(issuer,tx=>original.issue(owner.token,home,tx)),nextB=await transaction(issuer,tx=>original.issue(receiver.token,home,tx));assert.notEqual(nextA.signature,a.signature);assert.notEqual(nextB.signature,b.signature);assert.equal(nextA.payload.expiresAt,a.payload.expiresAt,'New scope cannot renew signed TOTP freshness');
 assert.equal(await transaction(coordinator,tx=>original.requested(next.scope,tx)),null,'Reapplication needs every home and successor again');
 await transaction(issuer,tx=>original.issue(owner.token,home2,tx));await transaction(issuer,tx=>original.issue(receiver2.token,home2,tx));
 const cap=await transaction(coordinator,tx=>original.requested(next.scope,tx));assert.ok(cap);assert.deepEqual(Object.keys(cap),['kind']);assert.equal(await transaction(coordinator,tx=>original.adopted(next.scope,cap,tx)),false,'Opaque claim proof cannot cross physical transactions');
 const wrongScope=generationFamilyModule.createGenerationFamilyOriginals({...options(next),scope:{...next.scope,inventoryDigest:'8'.repeat(64)}});assert.equal(await transaction(coordinator,tx=>wrongScope.readOriginal(home,owner.user,tx)),null,'Read-only original snapshot also binds the full generation scope');
 const wrongKey=generationFamilyModule.createGenerationFamilyOriginals({...options(next),key:randomBytes(32)});await assert.rejects(transaction(coordinator,tx=>wrongKey.requested(next.scope,tx)),/Independent exact generation original/);
 await assert.rejects(transaction(coordinator,tx=>tx.query("update private.kb_shared_deletion_journal set status='processing',lease_token=$2,lease_until=null where request_id=$1",[next.scope.requestID,next.scope.leaseToken])),/Current family original set|Exact generation originals|check constraint|not-null/,'Complete originals do not permit a missing processing lease expiry');
 let late=true;const journal=createDeletionJournal({transaction:work=>transaction(coordinator,work)},{'claim-ready':async(s,tx)=>{const c=await original.requested(s,tx);if(!c)return false;tx.beforeCommit('generation-original-adopted',()=>original.adopted(s,c,tx));if(late)policyLive=false;return true;}});
 await assert.rejects(journal.claimPrepared(next.scope),/Current transaction verification|Current original Auth policy/);policyLive=true;
 assert.equal((await admin.query('select status from private.kb_shared_deletion_journal where request_id=$1',[next.scope.requestID])).rows[0].status,'requested');
 late=false;assert.equal(await journal.claimPrepared(next.scope),true,'Actual journal requested->processing retains exact signed original set');
 assert.equal(await transaction(coordinator,tx=>original.verifyProcessingOriginal(next.scope,tx)),true);
 assert.equal(await transaction(coordinator,tx=>original.requested(next.scope,tx)),null,'Processing cannot start another requested proof');
 await assert.rejects(transaction(issuer,tx=>original.issue(owner.token,home,tx)),/Exact requested original frame/,'Issuance is requested-only, never renewed through processing');
 await assert.rejects(coordinator.query('select * from maintenance_private.generation_family_originals'),/permission denied/);
 await assert.rejects(admin.query('update maintenance_private.generation_family_originals set signature=repeat(\'a\',64) where generation_id=$1',[first.generationID]),/Immutable/);
 assert.deepEqual((await admin.query('select * from maintenance_private.generation_family_originals where generation_id=$1 order by home_id,actor_id',[first.generationID])).rows,saved);
 assert.equal((await admin.query('select inventory_captured from maintenance_private.account_deletion_requests where id=$1',[next.scope.apps[0].requestID])).rows[0].inventory_captured,false);
 assert.equal((await admin.query('select owner_id from public.homes where id=$1',[home])).rows[0].owner_id,owner.user);assert.equal((await admin.query('select name from public.products where id=$1',[product])).rows[0].name,'Generation original retained');
 console.log('Generation family originals: actual GoTrue password/TOTP owner+all successors across2homes, strict FK/Auth/session/AMR/current-policy checks, generation/home/epoch-bound immutable HMAC originals; AAL1/missing successor/wrong key/foreign tx refused. Cancel/reapply same home preserves old originals and does not renew TOTP expiry. Actual root claim/adopted/final deferred COMMIT and fresh processing reader pass; late policy failure rolls requested transition back; processing issuance refused. Native canonical captured=false, family ownership/content unchanged. NO handoff/post-handoff capture/file/paired final-COMMIT/hosted ownership/retention adoption.');
 return {originalOptions:options(next),scope:next.scope,generationID:next.generationID,owner,receiver,receiver2,home,home2,product,...extraCase};
}
